// ============================================================================
//  build.cs — <FAMILY NAME>
//  ---------------------------------------------------------------------------
//  THE SCRIPT IS THE SOURCE OF TRUTH. The .rfa is a build output.
//
//  This file must rebuild the family FROM THE TEMPLATE, from empty. It is not
//  a patch script. Every fix is folded back in here, or the next rebuild
//  silently reverts it.
//
//  Companion artifacts, same folder:
//    manifest.json   generated by the MANIFEST block at the bottom of this file
//    CHANGELOG.md    one entry per revision; quotes the user's defect report
//
//  Run:  explore_revit_data  (read-only build+verify)  or
//        execute_dynamic_query (it writes .rfa and manifest.json to disk)
//
//  Convention + rationale: paracore-mcp/Docs/FAMILY_ARTIFACT_WORKFLOW.md
//  API detail + traps:     skill://family-authoring/SKILL.md
// ============================================================================

// ⚠ System.IO and System.Text are NOT pre-imported — the manifest block needs them.
using System.IO;
using System.Text;

// ============================================================================
//  0. CONFIG  — the only part that changes between families
// ============================================================================

string FAMILY      = "ParametricChair";
string TEMPLATE    = "\\English\\Metric Generic Model.rft";   // ⚠ language subfolder
string OUT_RFA     = @"C:\Users\seyou\Documents\ParametricChair.rfa";
string OUT_MANIFEST= @"C:\Users\seyou\Documents\ParacoreFamilies\ParametricChair\manifest.json";

// ============================================================================
//  1. OPEN A FRESH FAMILY DOCUMENT
//     ⚠ Doc.FamilyCreate / Doc.FamilyManager THROW when the active document is a
//       PROJECT — and they do not return null, so a null-check will not save you.
// ============================================================================

Document famDoc = UIApp.Application.NewFamilyDocument(
    UIApp.Application.FamilyTemplatePath + TEMPLATE);

// ⚠⚠ Transact() CANNOT target a family document — ExecutionGlobals.Transact always
//    calls Tx.Transact(Doc, ...), so the Action<Document> overload hands you the
//    PROJECT. Build every transaction by hand, against famDoc.

// ============================================================================
//  2. tx1 — PARAMETERS AND THE FIRST TYPE
//     ⚠ A fresh family document has NO current type. NewType() must come FIRST,
//       or every Set() throws "There is no current type."
// ============================================================================

var tx1 = new Transaction(famDoc, "Parameters");
tx1.Start();
var fm = famDoc.FamilyManager;
fm.CurrentType = fm.NewType("Standard 450");

FamilyParameter pWidth = fm.AddParameter("Chair Width", GroupTypeId.Geometry, SpecTypeId.Length, false);
FamilyParameter pDepth = fm.AddParameter("Chair Depth", GroupTypeId.Geometry, SpecTypeId.Length, false);
FamilyParameter pSeatH = fm.AddParameter("Seat Height", GroupTypeId.Geometry, SpecTypeId.Length, false);
FamilyParameter pSeatT = fm.AddParameter("Seat Thickness", GroupTypeId.Geometry, SpecTypeId.Length, false);
FamilyParameter pSeatTop = fm.AddParameter("Seat Top", GroupTypeId.Geometry, SpecTypeId.Length, false);

// Formulas: set them AFTER both operands exist.
fm.SetFormula(pSeatTop, "Seat Height + Seat Thickness");

// Defaults, in internal units (feet). .InputUnit("mm") converts.
fm.Set(pWidth, 450.InputUnit("mm"));
fm.Set(pDepth, 450.InputUnit("mm"));
fm.Set(pSeatH, 405.InputUnit("mm"));
fm.Set(pSeatT, 45.InputUnit("mm"));
tx1.Commit();

// ============================================================================
//  3. tx2 — REFERENCE-PLANE SKELETON  (commit it — this regeneration is MANDATORY)
//     ⚠⚠ A reference plane's Reference is NOT a geometric reference until the
//        document regenerates. Dimension it in the SAME transaction without a
//        Regenerate() and you get:
//          ArgumentException: The references are not geometric references.
//        That reads like a bad reference. It is a TIMING problem.
//
//  ReferencePlane NewReferencePlane(XYZ bubbleEnd, XYZ freeEnd, XYZ cutVec, View pView)
//  Verified against Revit 2025 (RevitAPI 25.0.0.0) — Creation.ItemFactoryBase.
//  ⚠ cutVec must be perpendicular to (bubbleEnd - freeEnd), and the defining line
//    must lie in the plane of pView, or you get ArgumentsInconsistentException.
// ============================================================================

var tx2 = new Transaction(famDoc, "Skeleton");
tx2.Start();

View plan = new FilteredElementCollector(famDoc)
    .OfClass(typeof(ViewPlan))
    .Cast<View>()
    .FirstOrDefault(v => !v.IsTemplate);
if (plan == null) throw new InvalidOperationException("No non-template plan view in the family.");

double sk = 5000.InputUnit("mm");   // skeleton extents, generous — planes are infinite
double halfW = 450.InputUnit("mm");

// Plan planes: bubbleEnd/freeEnd span the plan, cutVec along Z.
// ⚠ Give each plane DISTINCT coordinates at creation. Creating two planes at the same
//   offset and moving them afterwards invites a degenerate-distance failure
//   (ArgumentException: "One of the conditions for the inputs was not satisfied")
//   as soon as anything is dimensioned between them.
// ⚠ cutVec must be perpendicular to (bubbleEnd − freeEnd): the line runs along +Y here,
//   cutVec is +Z.
ReferencePlane plLeft  = famDoc.FamilyCreate.NewReferencePlane(
    new XYZ(-halfW, 0, 0), new XYZ(-halfW, sk, 0), XYZ.BasisZ, plan);
ReferencePlane plRight = famDoc.FamilyCreate.NewReferencePlane(
    new XYZ( halfW, 0, 0), new XYZ( halfW, sk, 0), XYZ.BasisZ, plan);

tx2.Commit();   // ← the regeneration that makes the References usable

// ============================================================================
//  4. tx3 — LABELLED DRIVING DIMENSIONS
//     The dimension is what makes the parameter DRIVE. A parameter with no
//     dimension on it does nothing at all.
// ============================================================================

var tx3 = new Transaction(famDoc, "Driving dimensions");
tx3.Start();

var refsW = new ReferenceArray();
refsW.Append(plLeft.GetReference());
refsW.Append(plRight.GetReference());
var dimW = famDoc.FamilyCreate.NewLinearDimension(
    plan, Line.CreateBound(new XYZ(-halfW, 0, 0), new XYZ(halfW, 0, 0)), refsW);
dimW.FamilyLabel = pWidth;          // ← this is the line that makes it parametric
tx3.Commit();

// ============================================================================
//  5. tx4 — SKETCH PLANE, FORMS, AND THE VERTICAL STACK
//
//     ⚠ Offsets are measured from the SKETCH PLANE, not the family origin.
//       Build EVERY form on a Z = 0 plane and let Start/End place it.
//
//     ⚠⚠ In a stack, each form's Extrusion Start binds to the height of the form
//        DIRECTLY BELOW IT — never to one shared height.
//          legs  : (literal) 0    -> Leg Height
//          frame : Leg Height    -> Frame Top Height
//          seat  : Frame Top Height -> Seat Height
//        Binding an upper form's start to a LOWER height is the classic defect.
//        Measured 2026-10-01 on a 3-seater sofa: both armrests' Start were bound
//        to Leg Height (150) instead of Frame Top Height (300). 2 of 11 forms —
//        which is why it reads as a slip, not a systemic error.
// ============================================================================

var tx4 = new Transaction(famDoc, "Forms");
tx4.Start();

SketchPlane spXY = SketchPlane.Create(famDoc,
    Plane.CreateByNormalAndOrigin(XYZ.BasisZ, XYZ.Zero));   // one plane, Z = 0

CurveArray Rect(double w, double d)
{
    var loop = new CurveArray();
    loop.Append(Line.CreateBound(new XYZ(0, 0, 0), new XYZ(w, 0, 0)));
    loop.Append(Line.CreateBound(new XYZ(w, 0, 0), new XYZ(w, d, 0)));
    loop.Append(Line.CreateBound(new XYZ(w, d, 0), new XYZ(0, d, 0)));
    loop.Append(Line.CreateBound(new XYZ(0, d, 0), new XYZ(0, 0, 0)));
    return loop;
}

// --- EXTEND HERE: one block per form -----------------------------------------
// The example form spans the skeleton just built, so it follows Chair Width.
// ⚠ The sketch LINE must also be ALIGNED to the planes (tx5) or the form will not
//   follow the parameter — dimensioning the skeleton alone is not enough.
var seatProfile = new CurveArrArray();
seatProfile.Append(Rect(2 * halfW, 2 * halfW));
Extrusion seat = famDoc.FamilyCreate.NewExtrusion(true, seatProfile, spXY, 45.InputUnit("mm"));
try { seat.Name = "Seat"; } catch { }   // ⚠ Element.Name's setter throws on elements
                                        //    with no name parameter — never fatal here
// --- END EXTEND ---------------------------------------------------------------

// Bind each form's vertical extent to the parameter chain.
// ⚠ AssociateElementParameterToFamilyParameter takes the ELEMENT's Parameter,
//   obtained by built-in id — there is no name-based overload.
fm.AssociateElementParameterToFamilyParameter(
    seat.get_Parameter(BuiltInParameter.EXTRUSION_START_PARAM), pSeatH);
fm.AssociateElementParameterToFamilyParameter(
    seat.get_Parameter(BuiltInParameter.EXTRUSION_END_PARAM), pSeatTop);

tx4.Commit();

// ============================================================================
//  6. tx5 — ALIGNMENTS  (sketch line -> reference plane)
//     ⚠ Aligning a plane to a sketch line requires the line to be PARALLEL to
//       the plane (line direction ⊥ plane normal). A mismatch gives:
//         ArgumentException: The two references are not geometrically aligned...
//       That is a real geometry error, not a rejection of planes.
//
//     ⚠ A part that is neither dimensioned nor aligned DOES NOT MOVE.
//       Measured: a seat driven to 900 mm wide left its backrest at 450 mm.
//
//  Sketch-line references: seat.Sketch.GetAllElements() -> ElementIds -> ModelLine,
//  whose GeometryCurve.Reference is populated.
// ============================================================================

// var tx5 = new Transaction(famDoc, "Alignments");
// tx5.Start();
// foreach (var id in seat.Sketch.GetAllElements()) {
//     if (famDoc.GetElement(id) is ModelLine ml) {
//         var a = famDoc.FamilyCreate.NewAlignment(plan, plLeft.GetReference(), ml.GeometryCurve.Reference);
//         a.IsLocked = true;
//     }
// }
// tx5.Commit();

// ============================================================================
//  7. tx6 — DRIVE AND VERIFY
//     ⚠ NEVER call fm.Set(...) on a type you intend to keep. A drive test mutates
//       whatever CurrentType happens to be. Measured: two types ended up with
//       IDENTICAL geometry because a drive test wrote the second type's values
//       into the first.
//       → Create extra types AFTER all testing, or re-set the first type after.
// ============================================================================

var tx6 = new Transaction(famDoc, "Verify drive");
tx6.Start();
double savedW = fm.CurrentType.AsDouble(pWidth).Value;
fm.Set(pWidth, 900.InputUnit("mm"));
famDoc.Regenerate();
double movedW = fm.CurrentType.AsDouble(pWidth).Value;
fm.Set(pWidth, savedW);                     // put it back
famDoc.Regenerate();
tx6.Commit();

// ============================================================================
//  8. FURTHER TYPES  (after all drive testing)
// ============================================================================

var tx7 = new Transaction(famDoc, "Types");
tx7.Start();
fm.CurrentType = fm.NewType("Large 900");
fm.Set(pWidth, 900.InputUnit("mm"));
fm.Set(pDepth, 600.InputUnit("mm"));
tx7.Commit();

// ============================================================================
//  9. SAVE
//     ⚠⚠ `SaveAs` returns VOID — there is no bool to test (verified against the
//        Revit API reference, Document.SaveAs(String)). Checking it does not compile.
//     ⚠⚠ And `SaveAs(String)` raises InvalidOperationException — "There is an existing
//        file at filepath" — when the target already exists, which is EXACTLY the
//        rebuild case this template exists for. `OverwriteExistingFile` is therefore
//        required, not optional.
// ============================================================================

var sao = new SaveAsOptions();
sao.OverwriteExistingFile = true;
famDoc.SaveAs(OUT_RFA, sao);
if (!File.Exists(OUT_RFA))
    throw new InvalidOperationException("SaveAs produced no file: " + OUT_RFA);

// ============================================================================
//  10. MANIFEST  — the diffable projection of the .rfa
//      ⚠ This is what makes a revision auditable: rebuild, regenerate, diff.
//      ⚠⚠ start_binding / end_binding record the ASSOCIATION, never the value.
//         AsValueString() on an associated parameter returns the RESOLVED value,
//         so a hardcoded 300 and a bound 300 are indistinguishable by reading.
//         Only GetAssociatedFamilyParameter() tells you which you have.
// ============================================================================

string J(string s) => s == null ? "null" : "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
string N(double v) => v.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);

var sb = new StringBuilder();
sb.Append("{\n");
sb.Append("  \"family\": " + J(FAMILY) + ",\n");
sb.Append("  \"rfa\": " + J(OUT_RFA) + ",\n");
sb.Append("  \"rfa_bytes\": " + (new FileInfo(OUT_RFA).Length) + ",\n");
sb.Append("  \"generated\": " + J(DateTime.Now.ToString("yyyy-MM-ddTHH:mm:ss")) + ",\n");
sb.Append("  \"template\": " + J(TEMPLATE) + ",\n");

// ── types ──
var typeNames = new List<string>();
foreach (FamilyType t in fm.Types) typeNames.Add(J(t.Name));
sb.Append("  \"types\": [" + string.Join(", ", typeNames) + "],\n");

// ── parameters ──
sb.Append("  \"parameters\": [\n");
var paramLines = new List<string>();
foreach (FamilyParameter p in fm.Parameters) {
    if (p.IsBuiltIn) continue;                       // built-ins are noise
    var vals = new List<string>();
    foreach (FamilyType t in fm.Types) {
        double? d = t.AsDouble(p);
        if (d.HasValue) vals.Add(J(t.Name) + ": " + N(d.Value));
    }
    string formula = null;
    try { formula = p.Formula; } catch { }            // throws on a non-formula param
    paramLines.Add("    { \"name\": " + J(p.Definition.Name)
        + ", \"instance\": " + (p.IsInstance ? "true" : "false")
        + ", \"formula\": " + J(formula)
        + ", \"values\": {" + string.Join(", ", vals) + "} }");
}
sb.Append(string.Join(",\n", paramLines) + "\n");
sb.Append("  ],\n");

// ── forms + binding table ──
sb.Append("  \"forms\": [\n");
var formLines = new List<string>();
var formBbs  = new List<BoundingBoxXYZ>();
var formIds  = new List<int>();

// ⚠ FilteredElementCollector, not GetElements<T>() — GetElements has NO document
//   overload and always reads the ACTIVE document, so in family work the collector
//   is the only option. (The linter flags this line; it is correct here.)
var forms = new FilteredElementCollector(famDoc)
    .WhereElementIsNotElementType()
    .WhereElementIsViewIndependent()
    .OfClass(typeof(Extrusion));

foreach (Element e in forms) {
    var ps = e.get_Parameter(BuiltInParameter.EXTRUSION_START_PARAM);
    var pe = e.get_Parameter(BuiltInParameter.EXTRUSION_END_PARAM);
    var fs = fm.GetAssociatedFamilyParameter(ps);
    var fe = fm.GetAssociatedFamilyParameter(pe);

    // ⚠ get_BoundingBox(null) on an Extrusion reports in the EXTRUSION'S OWN
    //   sketch-plane frame, NOT model space — a seat on a plane at Z=405 reads
    //   @z0. Valid here only because every form shares one Z=0 plane; otherwise
    //   walk solid.Faces -> EdgeLoops -> Edge.AsCurve().GetEndPoint(k).
    var bb = e.get_BoundingBox(null);
    if (bb != null) { formBbs.Add(bb); formIds.Add(e.Id.IntegerValue); }

    string ext = bb == null ? "null"
        : "{\"x\":[" + N(bb.Min.X.OutputUnit("mm")) + "," + N(bb.Max.X.OutputUnit("mm")) + "]"
        + ",\"y\":[" + N(bb.Min.Y.OutputUnit("mm")) + "," + N(bb.Max.Y.OutputUnit("mm")) + "]"
        + ",\"z\":[" + N(bb.Min.Z.OutputUnit("mm")) + "," + N(bb.Max.Z.OutputUnit("mm")) + "]}";

    string ename = null;
    try { ename = e.Name; } catch { }        // ⚠ the getter can throw too

    formLines.Add("    { \"id\": " + e.Id.IntegerValue
        + ", \"name\": " + J(ename)
        + ", \"kind\": \"Extrusion\""
        + ", \"start_binding\": " + J(fs == null ? "(LITERAL)" : fs.Definition.Name)
        + ", \"end_binding\": "   + J(fe == null ? "(LITERAL)" : fe.Definition.Name)
        + ", \"extents_mm\": " + ext + " }");
}
sb.Append(string.Join(",\n", formLines) + "\n");
sb.Append("  ],\n");

// ── overlap count ──
// ⚠ strict < with a tolerance: forms that merely TOUCH at a shared Z
//   (frame ends 300, seat starts 300) must NOT count as intersecting.
int ov = 0;
var ovPairs = new List<string>();
for (int i = 0; i < formBbs.Count; i++)
for (int j = i + 1; j < formBbs.Count; j++) {
    var a = formBbs[i]; var b = formBbs[j];
    if (a.Min.X < b.Max.X - 1e-6 && b.Min.X < a.Max.X - 1e-6 &&
        a.Min.Y < b.Max.Y - 1e-6 && b.Min.Y < a.Max.Y - 1e-6 &&
        a.Min.Z < b.Max.Z - 1e-6 && b.Min.Z < a.Max.Z - 1e-6) {
        ov++; ovPairs.Add(formIds[i] + " x " + formIds[j]);
    }
}
sb.Append("  \"overlapping_pairs\": " + ov + ",\n");
sb.Append("  \"overlapping\": [" + string.Join(", ", ovPairs.ConvertAll(J)) + "],\n");

// ── warnings ──
var warnList = new List<string>();
foreach (var w in famDoc.GetWarnings()) warnList.Add(J(w.DescriptionText));
sb.Append("  \"warnings\": [" + string.Join(", ", warnList) + "]\n");
sb.Append("}\n");

Directory.CreateDirectory(Path.GetDirectoryName(OUT_MANIFEST));
File.WriteAllText(OUT_MANIFEST, sb.ToString());

// ── report ──
Println("FAMILY   : " + FAMILY);
Println("RFA      : " + OUT_RFA + "  (" + new FileInfo(OUT_RFA).Length + " B)");
Println("MANIFEST : " + OUT_MANIFEST);
Println("FORMS    : " + formBbs.Count);
Println("OVERLAP  : " + ov);
Println("WARNINGS : " + warnList.Count);
Println("DRIVE    : Chair Width " + savedW.OutputUnit("mm") + " -> 900 -> " + movedW.OutputUnit("mm"));

// ⚠ Close LAST — Document.Close() throws if any transaction is still open, and if
//   it throws inside one, the document is stuck and cannot be closed later.
famDoc.Close(false);
Println("CLOSED. docs open now = " + UIApp.Application.Documents.Size);

// ============================================================================
//  NEXT STEP, ALWAYS: append a CHANGELOG.md entry quoting the user's report
//  verbatim, plus the manifest diff. The diff is the proof the claim is true.
// ============================================================================
